            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "ईमानदारी से किया गया कर्म हमेशा फलदायक होता है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "प्रेम ही जीवन का आधार है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "ज्ञान की प्यास कभी नहीं बुझनी चाहिए।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "अंधकार के बाद प्रकाश अवश्य आता है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "संयम ही मनुष्य का सबसे बड़ा गुण है।", Author = "प्रेमचंद" },
