            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "मनुष्य वही है जो दूसरों का दुःख समझता है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "प्रेम में कोई स्वार्थ नहीं होता।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "ज्ञान ही मुक्ति का मार्ग है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "मानवता का सबसे बड़ा धर्म प्रेम है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "कर्म ही जीवन का आधार है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "जो व्यक्ति दूसरों के लिए जीता है, वही सच्चा मनुष्य है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "सांसारिक मोह मनुष्य को अंधा बना देता है।", Author = "प्रेमचंद" },
