            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "सच्ची दोस्ती अनमोल होती है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "ज्ञान वह दीपक है जो जीवन का मार्ग रोशन करता है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "संतोष ही परम सुख है।", Author = "प्रेमचंद" },
