            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "मनुष्य का सबसे बड़ा धन उसका चरित्र है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "अन्याय का विरोध करना ही न्याय का समर्थन करना है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "सादा जीवन और उच्च विचार ही आदर्श है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "जब तक इंसानियत बाकी है, तब तक उम्मीद बाकी है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "ज्ञान वह प्रकाश है जो जीवन के हर अंधकार को दूर कर देता है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "प्रेम एक ऐसी शक्ति है जो टूटे दिलों को जोड़ सकती है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "कर्म ही मनुष्य की पहचान है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "ईमानदारी का मार्ग कठिन हो सकता है, पर अंत में वही सफल होता है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "सत्य कभी छिपता नहीं, वह सदा उजागर होता है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "दूसरों का भला चाहना ही सच्चा धर्म है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "मनुष्य का सबसे बड़ा बल उसका विवेक है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "प्रेम का सच्चा स्वरूप त्याग में ही है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "ज्ञान वह कुंजी है जो हर दरवाजे को खोल सकती है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "जीवन का सच्चा अर्थ प्रेम करना और सेवा करना है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "अंधकार में भी आशा की किरण ढूँढनी चाहिए।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "जो दूसरों के दर्द को समझता है, वही सच्चा इंसान है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "ईमानदारी ही सबसे बड़ा गुण है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "सत्य ही परमेश्वर है।", Author = "प्रेमचंद" },
            new Quote { Id = "https://hi.wikiquote.org/wiki/प्रेमचंद", Text = "मनुष्य का सबसे बड़ा शत्रु उसका लालच है।", Author = " प्रेमचंद" },
